// v2: the secure core's user queries (#344).
//
// Every relation fragment appears once per section; the grant table only
// switches it on, through one boolean per (section, relation). Which grant
// opens which fragment is in core/gates.go.
//
// A user's role is chosen as everywhere (V2ReadCaller): one role per
// account, a guest's last, newest first. "Their workshop" is the one they
// are in: a guest's own, or the one entered in workshop mode. A user is "of
// own organisation" when their role belongs to the caller's organisation or
// they are in one of its workshops (v1); a guest of it is in one of its
// workshops. The organisation shown is their role's, or their workshop's;
// the one they are a member of is their role's only (head and staff): taking
// part in a workshop is no membership.
// The users the caller may see, for a list or for one user (id set): the
// List grants on UserCard for a list, the Read grants for one user.
func (q *Queries) V2Users(ctx context.Context, arg V2UsersParams) ([]V2UsersRow, error) {
	rows, err := q.db.QueryContext(ctx, v2Users,
		arg.AccountOwn,
		arg.Caller,
		arg.AccountOrganisation,
		arg.OwnOrganisation,
		arg.AccountEverywhere,
		arg.ContactOwn,
		arg.ContactOrganisation,
		arg.ContactEverywhere,
		arg.SecretsOwn,
		arg.SecretsOrganisation,
		arg.EditCardOwn,
		arg.EditCardGuest,
		arg.EditCardEverywhere,
		arg.EditAccountOwn,
		arg.EditAccountGuest,
		arg.EditAccountEverywhere,
		arg.EditContactOwn,
		arg.EditContactEverywhere,
		arg.DeleteGuest,
		arg.DeleteEverywhere,
		arg.ID,
		arg.MembersOf,
		arg.CardOwn,
		arg.CardOrganisation,
		arg.CardMember,
		arg.CardEverywhere,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []V2UsersRow
	for rows.Next() {
		var i V2UsersRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Email,
			&i.Language,
			&i.AgeGroup,
			&i.AiQualityTier,
			&i.DefaultApiKeyShareID,
			&i.GuestToken,
			&i.CreatedAt,
			&i.ModifiedAt,
			&i.Registered,
			&i.Role,
			&i.OrganisationID,
			&i.OrganisationName,
			&i.MemberOf,
			&i.WorkshopID,
			&i.WorkshopName,
			&i.MayReadAccount,
			&i.MayReadContact,
			&i.MayReadSecrets,
			&i.MayEditCard,
			&i.MayEditAccount,
			&i.MayEditContact,
			&i.MayDelete,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
